import "core-js/modules/es.array.push.js";
import "core-js/modules/es.iterator.constructor.js";
import "core-js/modules/es.iterator.filter.js";
import { useDisplay } from "vuetify";
import { GetAllListTickets } from "@/mixins/GetAllListTickets";
import TicketDetailsDialog from "./TicketDetailsDialog.vue";
export default {
  props: {
    filterStatus: String,
    search: String,
    fromDate: String,
    toDate: String
  },
  mixins: [GetAllListTickets],
  components: {
    TicketDetailsDialog
  },
  data: () => ({
    localFilterStatus: "ALL",
    height: 0,
    currentPage: 1,
    itemsPerPage: 15,
    DialogTicketDetails: false,
    CommonVuetifyObj: {},
    CreatedTicketDetailsObj: {},
    TicketDetailsObj: {},
    ListAllTickets: [],
    TableHeaders: [{
      title: "ID",
      value: "ticket_id"
    }, {
      title: "Initiated By",
      value: "reporter_name"
    }, {
      title: "Initiated On",
      value: "created_at"
    }, {
      title: "Title",
      value: "title"
    }, {
      title: "Category",
      value: "category_name"
    }, {
      title: "Assigned To",
      value: "assigned_to_name"
    }, {
      title: "Ticket Status",
      value: "status"
    }]
  }),
  watch: {
    search(newVal) {
      if (newVal !== undefined) {
        this.currentPage = 1;
      }
    },
    filterStatus(newVal) {
      this.localFilterStatus = newVal;
      this.currentPage = 1;
    },
    fromDate() {
      this.currentPage = 1;
    },
    toDate() {
      this.currentPage = 1;
    }
  },
  computed: {
    AllTickets() {
      const items = this.ListAllTickets || [];
      const all = items.length;
      const claimed = items.filter(item => item.claim_status === "CLAIMED").length;
      const unclaimed = items.filter(item => item.claim_status === "UNCLAIMED").length;
      const resolved = items.filter(item => item.status === "RESOLVED").length;
      const inProgress = items.filter(item => item.status === "IN_PROGRESS").length;
      const open = items.filter(item => item.status === "OPEN").length;
      const onHold = items.filter(item => item.status === "ONHOLD").length;
      const closed = items.filter(item => item.status === "CLOSED").length;
      const reopened = items.filter(item => item.status === "REOPEN").length;
      return [{
        title: "All",
        description: all
      }, {
        title: "Claimed",
        description: claimed
      }, {
        title: "Unclaimed",
        description: unclaimed
      }, {
        title: "Open",
        description: open
      }, {
        title: "In Progress",
        description: inProgress
      }, {
        title: "Resolved",
        description: resolved
      }, {
        title: "On Hold",
        description: onHold
      }, {
        title: "Closed",
        description: closed
      }, {
        title: "Reopened",
        description: reopened
      }];
    },
    filteredItems() {
      let items = this.ListAllTickets || [];
      items.sort((a, b) => b.created_at - a.created_at);
      let fromTS = null;
      let toTS = null;
      if (this.fromDate) {
        const f = new Date(this.fromDate);
        f.setHours(0, 0, 0, 0);
        fromTS = f.getTime() / 1000;
      }
      if (this.toDate) {
        const t = new Date(this.toDate);
        t.setHours(23, 59, 59, 999);
        toTS = t.getTime() / 1000;
      }
      items = items.filter(item => {
        const created = Number(item.created_at);
        if (fromTS && created < fromTS) return false;
        if (toTS && created > toTS) return false;
        return true;
      });
      if (this.localFilterStatus && this.localFilterStatus !== "ALL") {
        if (this.localFilterStatus === "CLAIMED") {
          items = items.filter(item => item.claim_status === "CLAIMED");
        } else if (this.localFilterStatus === "UNCLAIMED") {
          items = items.filter(item => item.claim_status === "UNCLAIMED");
        } else {
          items = items.filter(item => item.status === this.localFilterStatus);
        }
      }
      if (this.search && this.search.trim() !== "") {
        const searchLower = this.search.toLowerCase().trim();
        const searchTrim = this.search.trim();
        items = items.filter(item => {
          return (item.title || "").toLowerCase().includes(searchLower) || (item.reporter_name || "").toLowerCase().includes(searchLower) || (item.category_name || "").toLowerCase().includes(searchLower) || (item.assigned_to_name || "").toLowerCase().includes(searchLower) || item.ticket_id.toString().includes(searchTrim);
        });
      }
      return items;
    },
    totalItems() {
      return this.filteredItems.length;
    },
    paginatedItems() {
      const start = (this.currentPage - 1) * this.itemsPerPage;
      const end = start + this.itemsPerPage;
      return this.filteredItems.slice(start, end);
    },
    pageCount() {
      return Math.ceil(this.filteredItems.length / this.itemsPerPage);
    },
    visiblePages() {
      const totalPages = this.pageCount;
      const current = this.currentPage;
      const delta = 2;
      let start = Math.max(1, current - delta);
      let end = Math.min(totalPages, current + delta);
      if (end - start < 4) {
        if (start === 1) {
          end = Math.min(totalPages, start + 4);
        } else {
          start = Math.max(1, end - 4);
        }
      }
      const pages = [];
      for (let i = start; i <= end; i++) {
        pages.push(i);
      }
      return pages;
    }
  },
  async mounted() {
    this.CommonVuetifyObj = useDisplay();
    await this.GetAllListTicketsMethod();
    this.$emit("update-ticket-count", this.ListAllTickets.length);
  },
  methods: {
    async RefreshAllTickets() {
      await this.GetAllListTicketsMethod();
    },
    ConvertDate(created_at) {
      if (!created_at) return "TBD";
      if (isNaN(created_at)) return "Invalid Date";
      const date = new Date(created_at * 1000);
      const yyyy = date.getFullYear();
      const mm = String(date.getMonth() + 1).padStart(2, "0");
      const dd = String(date.getDate()).padStart(2, "0");
      return `${dd}-${mm}-${yyyy}`;
    },
    filterByStatus(title) {
      const mapper = {
        Open: "OPEN",
        Claimed: "CLAIMED",
        Unclaimed: "UNCLAIMED",
        "In Progress": "IN_PROGRESS",
        "On Hold": "ONHOLD",
        Resolved: "RESOLVED",
        Closed: "CLOSED",
        Reopened: "REOPEN"
      };
      const status = mapper[title] || "ALL";
      this.currentPage = 1;
      this.localFilterStatus = status;
      this.$emit("update:filterStatus", status);
    },
    getStatusColor(status) {
      switch (status) {
        case "All":
          return "#2196F3";
        case "Claimed":
          return "green";
        case "Unclaimed":
          return "#FF5722";
        case "Open":
          return "blue";
        case "In Progress":
          return "fuchsia";
        case "On Hold":
          return "orange";
        case "Resolved":
          return "#607D8B";
        case "Closed":
          return "green";
        case "Reopened":
          return "#311B92";
        default:
          return "black";
      }
    },
    isActiveStatus(title) {
      const mapper = {
        Open: "OPEN",
        Claimed: "CLAIMED",
        Unclaimed: "UNCLAIMED",
        "In Progress": "IN_PROGRESS",
        "On Hold": "ONHOLD",
        Resolved: "RESOLVED",
        Closed: "CLOSED",
        Reopened: "REOPEN"
      };
      const status = mapper[title] || "ALL";
      return this.localFilterStatus === status;
    },
    OpenDialogTicketDetails(event, rowItem) {
      this.TicketDetailsObj = rowItem.item;
      this.DialogTicketDetails = true;
    },
    DialogTicketDetailsEmit(Toggle) {
      this.DialogTicketDetails = false;
      this.$emit("refresh-data", Toggle);
    }
  }
};
